// Stamps out the combined AI Usage Tracker from the same shared engine the single-provider
// plugins use:
//   node scripts/build-tracker.mjs
// Unlike build-provider.mjs this one does not select a provider. Its BUILD.id is not in the
// provider registry, which is what puts the engine into combined mode (see IS_COMBINED).
import { writeFileSync, mkdirSync } from "node:fs";
import { execSync } from "node:child_process";
import { PROVIDERS } from "./providers.config.mjs";

// Order shown in the picker and the rollup. Mirrors PROVIDER_IDS in src/providers/active.ts.
const IDS = ["claude", "openai", "codex", "cursor", "gemini", "copilot", "grok", "perplexity"];

const TRACKER = {
	id: "ai-usage-tracker",
	name: "AI Usage Tracker",
	// com.packrat is the brand's technical namespace. The eight single-provider plugins
	// still use com.ratpack because they are published and a UUID change would orphan
	// every existing install; new products use the correct namespace.
	uuid: "com.packrat.ai-usage-tracker",
	actionUuid: "com.packrat.ai-usage-tracker.monitor",
	brand: "#2BE86A", // Packrat accent: this product belongs to no single provider
	version: "1.0.1.0",
};

const dir = `${TRACKER.uuid}.sdPlugin`;
const meta = IDS.map((id) => {
	const p = PROVIDERS[id];
	return { id, display: p.display, brand: p.brand, autoload: !!p.autoload, windows: p.windows ?? [], help: p.help ?? "" };
});

function buildInfoTs(cfg) {
	const b = { id: cfg.id, name: cfg.name, uuid: cfg.uuid, actionUuid: cfg.actionUuid, brand: cfg.brand };
	return (
		`// Generated by scripts/build-tracker.mjs. Do not edit by hand.\n` +
		`export interface BuildInfo { id: string; name: string; uuid: string; actionUuid: string; brand: string; }\n` +
		`export const BUILD: BuildInfo = ${JSON.stringify(b, null, 2)};\n`
	);
}

function manifest(cfg) {
	return {
		$schema: "https://schemas.elgato.com/streamdeck/plugins/manifest.json",
		Name: cfg.name,
		Version: cfg.version,
		Author: "Packrat",
		Description:
			"Every AI limit you are burning through, on one key. Claude, ChatGPT, Codex, Cursor, Gemini, Copilot, Grok and Perplexity, live and colour coded.",
		Category: cfg.name,
		CategoryIcon: "imgs/plugin/category-icon",
		Icon: "imgs/plugin/marketplace",
		CodePath: "bin/plugin.js",
		SDKVersion: 3,
		Software: { MinimumVersion: "6.9" },
		OS: [
			{ Platform: "windows", MinimumVersion: "10" },
			{ Platform: "mac", MinimumVersion: "12" },
		],
		Nodejs: { Version: "20" },
		UUID: cfg.uuid,
		Actions: [
			{
				Name: "AI Usage",
				UUID: cfg.actionUuid,
				Icon: "imgs/actions/usage/icon",
				Tooltip: "Show one provider, or all of them at once. Short press: style. Long press: window.",
				PropertyInspectorPath: "ui/usage.html",
				Controllers: ["Keypad"],
				UserTitleEnabled: false,
				States: [{ Image: "imgs/actions/usage/key", TitleAlignment: "middle" }],
			},
		],
	};
}

function piHtml(cfg, providers) {
	const styleOpts = [
		["ring", "Ring"],
		["full", "Full (fills up)"],
		["number", "Big Number"],
		["bigdate", "Big Time"],
		["countdown", "Countdown (time left)"],
		["sparkline", "Sparkline (history)"],
		["heatmap", "Weekly Heatmap"],
		["status", "Status"],
	]
		.map(([v, l]) => `<option value="${v}">${l}</option>`)
		.join("");

	return `<!DOCTYPE html>
<html>
	<head>
		<meta charset="utf-8" />
		<style>
			:root { --accent: ${cfg.brand}; }
			body { font-family: -apple-system, "Segoe UI", sans-serif; background: #2d2d2d; color: #dfdfdf; margin: 0; padding: 10px; font-size: 13px; }
			.label { font-size: 11px; color: #9a9aa2; text-transform: uppercase; letter-spacing: .3px; margin: 12px 0 5px; }
			.acct { display: flex; gap: 6px; margin-bottom: 6px; }
			.acct .name { width: 36%; }
			.acct .tok { flex: 1; }
			input, select { background: #3d3d3d; color: #fff; border: 1px solid #1c1c1f; border-radius: 4px; padding: 6px; font-size: 13px; box-sizing: border-box; }
			input:focus, select:focus { outline: none; border-color: var(--accent); }
			.acct .rm { background: #3d3d3d; color: #ff6b6b; border: 1px solid #1c1c1f; border-radius: 4px; cursor: pointer; width: 30px; padding: 0; }
			.add { background: var(--accent); color: #111; border: none; border-radius: 4px; padding: 6px 10px; cursor: pointer; font-weight: 700; font-size: 12px; margin-top: 2px; }
			.row { display: flex; align-items: center; gap: 8px; margin: 6px 0; }
			.row > label { width: 78px; font-size: 12px; color: #cfcfcf; }
			.row select, .row input[type=text] { flex: 1; }
			.badge { font-size: 11px; color: #9fe0a0; background: rgba(43,232,106,.12); border: 1px solid rgba(43,232,106,.35); border-radius: 10px; padding: 2px 8px; display: inline-block; margin-top: 8px; }
			.warn { font-size: 11px; color: #ffd60a; margin-top: 5px; }
			details { background: #262626; border-radius: 6px; margin: 8px 0; padding: 2px 10px; }
			summary { cursor: pointer; font-weight: 600; padding: 7px 0; color: #fff; }
			.prov > summary { font-size: 12px; display: flex; align-items: center; gap: 8px; }
			.prov .dot { width: 8px; height: 8px; border-radius: 50%; display: inline-block; }
			.prov .on { margin-left: auto; font-size: 11px; color: #9a9aa2; font-weight: 500; }
			.browser summary { font-size: 12px; }
			ol { font-size: 12px; line-height: 1.6; color: #cfcfcf; padding-left: 18px; margin: 4px 0; }
			code { background: #1c1c1f; border: 1px solid #3a3a3a; border-radius: 4px; padding: 1px 5px; color: var(--accent); font-family: ui-monospace, Consolas, monospace; font-size: 11px; }
			.hint { font-size: 11px; color: #9a9aa2; line-height: 1.5; margin: 6px 0; }
			p { font-size: 12px; color: #cfcfcf; line-height: 1.5; margin: 6px 0; }
			.chk { display: flex; align-items: center; gap: 6px; font-size: 12px; color: #cfcfcf; margin: 6px 0; }
			.chk input { width: auto; }
		</style>
	</head>
	<body>
		<div class="label">Providers</div>
		<div class="hint">Switch on the ones you use and paste a token for each. Anything switched on keeps updating in the background, so a key is never waiting on its first reading.</div>
		<div id="providers"></div>

		<div class="label">This key</div>
		<div class="row"><label>Shows</label><select id="provider"></select></div>
		<div class="row" id="accountRow"><label>Account</label><select id="account"></select></div>
		<div class="row" id="windowRow"><label>Type</label><select id="window"></select></div>
		<div class="row" id="styleRow"><label>Style</label><select id="style">${styleOpts}</select></div>
		<div class="row"><label>Theme</label><select id="theme"><option value="oled">OLED (true black)</option><option value="midnight">Midnight</option><option value="light">Light</option></select></div>
		<div class="row"><label>Refresh</label><select id="interval"><option value="10">Every 10 sec</option><option value="30">Every 30 sec</option><option value="60">Every 1 min</option><option value="120">Every 2 min</option><option value="300">Every 5 min</option></select></div>
		<div class="row"><label>Display</label><label style="width:auto;font-size:12px"><input type="checkbox" id="showRemaining" style="width:auto;margin-right:6px" />Show remaining % (off = used)</label></div>
		<div class="hint" id="allHint" style="display:none">Showing every switched-on provider on this one key. Press it to refresh them all.</div>
		<div class="hint" id="keyHint">Tip: <b>short-press</b> a key to change style, <b>long-press</b> to switch type.</div>

		<div><span class="badge">🔒 100% local, never shared, only used to read your own usage.</span></div>
		<div class="warn">⚠️ Treat these tokens like passwords.</div>

		<div class="label">Demo</div>
		<div class="chk"><input type="checkbox" id="demo" /><span>Show sample data on every key</span></div>
		<div class="hint">Try the styles without an account. Sample values sweep through every colour state. Turn this off to go back to your real usage.</div>

		<script>
			var PROVIDERS = ${JSON.stringify(providers)};
			var ALL = "__all__";
			var ws, ctx, action = {}, global = { providerAccounts: {}, enabledProviders: [], interval: "120" };

			function send(o) { ws.send(JSON.stringify(o)); }
			function saveGlobal() { send({ event: "setGlobalSettings", context: ctx, payload: global }); }
			function saveAction() { send({ event: "setSettings", context: ctx, payload: action }); }
			function setVal(elid, v) { var el = document.getElementById(elid); if (el) el.value = v; }
			function metaFor(id) { for (var i = 0; i < PROVIDERS.length; i++) if (PROVIDERS[i].id === id) return PROVIDERS[i]; return null; }
			function accountsOf(id) {
				if (!global.providerAccounts) global.providerAccounts = {};
				if (!Array.isArray(global.providerAccounts[id])) global.providerAccounts[id] = [];
				return global.providerAccounts[id];
			}
			function isEnabled(id) { return (global.enabledProviders || []).indexOf(id) !== -1; }
			function setEnabled(id, on) {
				var list = (global.enabledProviders || []).filter(function (x) { return x !== id; });
				if (on) list.push(id);
				global.enabledProviders = list;
			}

			function accountEditor(p) {
				var wrap = document.createElement("div");
				var list = document.createElement("div");
				accountsOf(p.id).forEach(function (a, i) {
					var row = document.createElement("div"); row.className = "acct";
					var name = document.createElement("input"); name.className = "name"; name.placeholder = "Name"; name.value = a.name || "";
					name.oninput = function () { a.name = name.value; saveGlobal(); renderAccountSelect(); };
					var tok = document.createElement("input"); tok.className = "tok"; tok.type = "password"; tok.placeholder = "session token"; tok.value = a.token || "";
					tok.oninput = function () { a.token = tok.value; saveGlobal(); };
					var rm = document.createElement("button"); rm.className = "rm"; rm.textContent = "✕";
					rm.onclick = function () { accountsOf(p.id).splice(i, 1); saveGlobal(); renderProviders(); renderAccountSelect(); };
					row.appendChild(name); row.appendChild(tok); row.appendChild(rm); list.appendChild(row);
				});
				var add = document.createElement("button"); add.className = "add"; add.textContent = "+ Add account";
				add.onclick = function () {
					var accts = accountsOf(p.id);
					accts.push({ name: "Account " + (accts.length + 1), token: "" });
					saveGlobal(); renderProviders(); renderAccountSelect();
				};
				wrap.appendChild(list); wrap.appendChild(add);
				return wrap;
			}

			function renderProviders() {
				var host = document.getElementById("providers");
				host.innerHTML = "";
				PROVIDERS.forEach(function (p) {
					var d = document.createElement("details"); d.className = "prov";
					var s = document.createElement("summary");
					var dot = document.createElement("span"); dot.className = "dot"; dot.style.background = p.brand;
					var nm = document.createElement("span"); nm.textContent = p.display;
					var on = document.createElement("label"); on.className = "on";
					var cb = document.createElement("input"); cb.type = "checkbox"; cb.checked = isEnabled(p.id);
					cb.onclick = function (e) { e.stopPropagation(); };
					cb.onchange = function () { setEnabled(p.id, cb.checked); saveGlobal(); renderProviderSelect(); };
					on.appendChild(cb); on.appendChild(document.createTextNode(" on"));
					s.appendChild(dot); s.appendChild(nm); s.appendChild(on);
					d.appendChild(s);
					if (p.autoload) {
						var h = document.createElement("div"); h.className = "hint";
						h.textContent = "Auto-detects your local " + p.display + " login, so usually there is nothing to paste. Add a token only if usage is not updating.";
						d.appendChild(h);
					}
					d.appendChild(accountEditor(p));
					var help = document.createElement("details");
					help.innerHTML = "<summary>How do I get a token?</summary><div class='hint'>" + p.help + "</div>";
					d.appendChild(help);
					host.appendChild(d);
				});
			}

			function renderProviderSelect() {
				var sel = document.getElementById("provider");
				sel.innerHTML = "";
				var all = document.createElement("option"); all.value = ALL; all.textContent = "All providers (rollup)";
				sel.appendChild(all);
				PROVIDERS.forEach(function (p) {
					var o = document.createElement("option"); o.value = p.id;
					o.textContent = p.display + (isEnabled(p.id) ? "" : " (off)");
					sel.appendChild(o);
				});
				sel.value = action.provider || ALL;
			}

			function renderWindowSelect() {
				var sel = document.getElementById("window");
				var p = metaFor(action.provider);
				sel.innerHTML = "";
				if (!p) return;
				p.windows.forEach(function (w) {
					var o = document.createElement("option"); o.value = w.value; o.textContent = w.label; sel.appendChild(o);
				});
				sel.value = action.window || (p.windows[0] && p.windows[0].value) || "";
			}

			function renderAccountSelect() {
				var sel = document.getElementById("account");
				sel.innerHTML = "";
				var def = document.createElement("option"); def.value = ""; def.textContent = "Default (first account)";
				sel.appendChild(def);
				if (action.provider && action.provider !== ALL) {
					accountsOf(action.provider).forEach(function (a) {
						var o = document.createElement("option"); o.value = a.name; o.textContent = a.name || "(unnamed)"; sel.appendChild(o);
					});
				}
				sel.value = action.account || "";
			}

			function renderAction() {
				if (!action.provider) action.provider = ALL;
				var rollup = action.provider === ALL;
				// The rollup already spans providers, so a single account, window or style
				// would have nothing to apply to.
				["accountRow", "windowRow", "styleRow"].forEach(function (id) {
					document.getElementById(id).style.display = rollup ? "none" : "flex";
				});
				document.getElementById("allHint").style.display = rollup ? "block" : "none";
				document.getElementById("keyHint").style.display = rollup ? "none" : "block";
				setVal("style", action.style || "ring");
				setVal("theme", action.theme || "oled");
				document.getElementById("showRemaining").checked = !!action.showRemaining;
				renderProviderSelect(); renderWindowSelect(); renderAccountSelect();
			}

			document.getElementById("provider").onchange = function () {
				action.provider = this.value;
				// Window keys are provider specific, so a stale one would render "not available".
				delete action.window; delete action.account;
				saveAction(); renderAction();
			};
			document.getElementById("account").onchange = function () { action.account = this.value; saveAction(); };
			document.getElementById("window").onchange = function () { action.window = this.value; saveAction(); };
			document.getElementById("style").onchange = function () { action.style = this.value; saveAction(); };
			document.getElementById("theme").onchange = function () { action.theme = this.value; saveAction(); };
			document.getElementById("showRemaining").onchange = function () { action.showRemaining = this.checked; saveAction(); };
			document.getElementById("interval").onchange = function () { global.interval = this.value; saveGlobal(); };
			document.getElementById("demo").onchange = function () { global.demo = this.checked; saveGlobal(); };

			window.connectElgatoStreamDeckSocket = function (port, uuid, registerEvent, info, actionInfo) {
				ctx = uuid;
				try { action = JSON.parse(actionInfo).payload.settings || {}; } catch (e) {}
				ws = new WebSocket("ws://127.0.0.1:" + port);
				ws.onopen = function () {
					send({ event: registerEvent, uuid: uuid });
					send({ event: "getGlobalSettings", context: uuid });
					renderAction();
				};
				ws.onmessage = function (e) {
					var m = JSON.parse(e.data);
					if (m.event === "didReceiveGlobalSettings") {
						global = m.payload.settings || {};
						if (!global.providerAccounts) global.providerAccounts = {};
						if (!Array.isArray(global.enabledProviders)) global.enabledProviders = [];
						setVal("interval", global.interval || "120");
						document.getElementById("demo").checked = !!global.demo;
						renderProviders(); renderAction();
					} else if (m.event === "didReceiveSettings") {
						action = m.payload.settings || {};
						renderAction();
					}
				};
			};
		</script>
	</body>
</html>
`;
}

console.log(`\n▶ Building ${TRACKER.name} (${TRACKER.uuid})`);

// 1. Identity. An id outside the provider registry is what selects combined mode.
writeFileSync("src/providers/build-info.ts", buildInfoTs(TRACKER));

// 2. Manifest + property inspector.
mkdirSync(`${dir}/ui`, { recursive: true });
writeFileSync(`${dir}/manifest.json`, JSON.stringify(manifest(TRACKER), null, "\t") + "\n");
writeFileSync(`${dir}/ui/usage.html`, piHtml(TRACKER, meta));

// 3. Icons, bundle, pack. No provider logo overlay here: the product is not one provider,
// so the neutral gauge is rendered white on transparent for the in-app icon slots.
const env = { ...process.env, SD_PLUGIN_DIR: dir, SD_BRAND: TRACKER.brand, SD_WHITE_INAPP: "1" };
execSync("node scripts/gen-icons.mjs", { env, stdio: "inherit" });
execSync("npx rollup -c", { env, stdio: "inherit" });
execSync(`npx streamdeck pack ${dir} --output dist --force`, { stdio: "inherit" });

// 4. Restore the repo default to Claude so `npm run build` and the IDE stay on Claude,
// matching what build-provider.mjs does.
writeFileSync(
	"src/providers/build-info.ts",
	`// Generated by scripts/build-provider.mjs. Do not edit by hand.\n` +
		`export interface BuildInfo { id: string; name: string; uuid: string; actionUuid: string; brand: string; }\n` +
		`export const BUILD: BuildInfo = ${JSON.stringify(
			{
				id: PROVIDERS.claude.id,
				name: PROVIDERS.claude.name,
				uuid: PROVIDERS.claude.uuid,
				actionUuid: PROVIDERS.claude.actionUuid,
				brand: PROVIDERS.claude.brand,
			},
			null,
			2,
		)};\n`,
);

console.log(`✔ ${TRACKER.name} → dist/${TRACKER.uuid}.streamDeckPlugin\n`);
